const wikiUrl = (name) =>
  `https://theforeverwinter.wiki.gg/wiki/${encodeURIComponent(name.replaceAll(" ", "_"))}`;

const slug = (value) => value
  .toLowerCase()
  .normalize("NFKD")
  .replace(/[’']/g, "")
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-|-$/g, "");

const quest = (name, faction, location, objective, options = {}) => ({
  id: slug(name),
  name,
  faction,
  location,
  objective,
  wiki: wikiUrl(name),
  ...options,
});

const line = (id, name, giver, unlock, accent, quests) => {
  const normalized = quests.map((entry, index) => ({
    ...entry,
    lineId: id,
    radiant: false,
    requires: entry.requires === undefined
      ? (index ? [quests[index - 1].id] : [])
      : entry.requires,
  }));
  return { id, name, giver, unlock, accent, quests: normalized };
};

